//! The runtime behind Rust clients generated by [Truewire](https://truewire.dev): the
//! crate a generated package depends on, and the contract a hand-written core satisfies.
//!
//! - [`contract`]: the traits a core implements ([`HttpEndpoint`], [`CommandEndpoint`],
//!   [`StreamEndpoint`]) and the call shapes generated code hands them.
//! - [`http`]: [`HttpClient`] over `reqwest`, with wire-level [`recording`](HttpClient::recording).
//! - [`validation`]: `serde` decode/dump with JSON-pointer errors; [`types`] the wire
//!   newtypes for every narrowed scalar format; [`times`] and [`decimal`] the converters.
//! - [`paging`]: [`PaginatedResponse`], the resumable, retry-safe walk generated
//!   `<method>_paged` methods return.
//! - [`ws`]: [`Socket`](ws::Socket) over `tokio-tungstenite` with request/reply
//!   correlation, channel subscriptions and serial acknowledgements.
//! - [`errors`]: the one [`Error`] enum every function here returns.
//! - `proto` (feature `proto`): protobuf messages as JSON values, for binary frames.
//! - `grpc` (feature `grpc`): unary gRPC calls over those messages.
//!
//! See `docs/rust.md` in the repository for what a core must implement.

pub mod contract;
pub mod decimal;
pub mod errors;
#[cfg(feature = "grpc")]
pub mod grpc;
pub mod http;
pub mod paging;
#[cfg(feature = "proto")]
pub mod proto;
pub mod times;
pub mod types;
pub mod validation;
pub mod ws;

pub use bigdecimal;
pub use chrono;
pub use serde_json;

pub use contract::{
    CallOptions, CommandCall, CommandEndpoint, GrpcCall, GrpcEndpoint, HttpCall, HttpEndpoint, StreamEndpoint,
    SubscribeCall, Transport,
};
